pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    assert!(N >= 0);
    // Given: N <= 0x3FFF_FFFF
    let n_usize: usize = N as usize;

    assert!(a.len() == n_usize, "array a must have length N");
    assert!(b.len() == n_usize, "array b must have length N");

    let mut sum: i32 = 0;

    for i in 0..n_usize {
        let i_i32 = i as i32;
        let bi = b[i];

        // Given: b[i] is either i or i+1 for all valid i
        assert!(
            bi == i_i32 || bi == i_i32 + 1,
            "b[i] must be either i or i+1"
        );

        let v = if bi == i_i32 { 1 } else { 2 };
        a[i] = v;
        sum += v;
    }

    sum
}